mapper.select:
SELECT

FROM SysUserInfo a , SysOrganization b
WHERE a.orgId = b.id AND 1 = 1

    and a.id = #{id}


    and a.orgId = #{orgId}


    and a.userName like CONCAT('%',#{userName}, '%')


    and a.trueName like CONCAT('%',#{trueName}, '%')


    and a.phone like CONCAT('%',#{phone}, '%')


    and a.gender = #{gender}


    and a.active = #{active}


    and a.idCard like '%'||#{idCard}||'%'


    ORDER BY ${orderBy}

SELECT

FROM SysUserInfo a WHERE 1 = 1
AND a.userName = #{userName}

SELECT

FROM
UserRole b
LEFT JOIN SysUserInfo a ON b.userId = a.id
WHERE 1 = 1

    and b.roleId = #{roleId}


    and a.active = #{active}


    and a.orgId = #{orgId}
